func (this *Shell) setEnabled_(enabled bool) {
	this.CheckWidget()
	if ((this.state & WidgetDISABLED) == 0) == enabled {
		return
	}
	var display *Display = this.display
	var control *Control = nil
	var fixFocus bool = false
	if !enabled {
		if display.focusEvent != FocusOut {
			control = display.GetFocusControl()
			fixFocus = this.IsFocusAncestor(control)
		}
	}
	if enabled {
		this.state &= ^WidgetDISABLED
	} else {
		this.state |= WidgetDISABLED
	}
	this.impl.enableWidget_(enabled)
	if this.IsDisposed() {
		return
	}
	if !gtk.GTKGTK4 {
		if enabled {
			if this.enableWindow != 0 {
				this.CleanupEnableWindow()
			}
		} else {
			var parentHandle int64 = this.shellHandle
			gtk.GTKGtk_widget_realize(parentHandle)
			var window int64 = this.Gtk_widget_get_window(parentHandle)
			var rect *Rectangle = this.impl.getBoundsInPixels_()
			var attributes gtk.GdkWindowAttr = gtk.GdkWindowAttr{}
			attributes.Width = rect.Width
			attributes.Height = rect.Height
			attributes.Event_mask = (-1 & ^gtk.OSExposureMask)
			attributes.Wclass = gtk.GDKGDK_INPUT_ONLY
			attributes.Window_type = gtk.GDKGDK_WINDOW_CHILD
			this.enableWindow = gtk.GTK3Gdk_window_new(window, &attributes, 0)
			if this.enableWindow != 0 {
				if this.cursor != (nil) {
					gtk.GDKGdk_window_set_cursor(this.enableWindow, this.cursor.Handle)
				}
				gtk.GDKGdk_window_set_user_data(this.enableWindow, parentHandle)
				gtk.GDKGdk_window_show(this.enableWindow)
			}
		}
	}
	if fixFocus {
		this.FixFocus(control)
	}
	if enabled && display.activeShell == this {
		if !this.RestoreFocus() {
			this.TraverseGroup(false)
		}
	}
}

